    correction: [{"quoi":"ما تقوله العبارة","math":"العبارة تدّعي أنّ الزوجية و الفردية تكفيان للأوّلية فيما بينهما"},{"quoi":"نبحث عن مثال مضادّ","math":"نأخذ 18 و هو زوجي، و 45 و هو فردي"},{"quoi":"نفكّك العددين","math":"<span dir=\"ltr\" class=\"expr\">18 = 9 × 2</span> و <span dir=\"ltr\" class=\"expr\">45 = 9 × 5</span>"},{"quoi":"نحسب القاسم المشترك","math":"العدد 9 يقسم 18 و يقسم 45"},{"quoi":"نستنتج","math":"ق.م.أ لهما يقبل القسمة على 9 فهو ليس 1"},{"quoi":"الجواب","math":"خطأ"}],
