    correction: [{"quoi":"نقسم المعامل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">24 = 6 × 4</span>"},{"quoi":"نقسم الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">42 = 6 × 7</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">24n + 42 = 6(4n + 7)</span>"},{"quoi":"نستنتج","math":"العبارة مكتوبة <span dir=\"ltr\" class=\"expr\">6 ×</span> عدد صحيح، مهما يكن n"},{"quoi":"الجواب","math":"صواب"}],
