    correction: [{"quoi":"شرط الباقي","math":"الباقي في القسمة على 9 يجب أن يكون أصغر تماما من 9"},{"quoi":"نقارن","math":"<span dir=\"ltr\" class=\"expr\">11 &gt; 9</span>"},{"quoi":"العدد المقترح ليس باقيا","math":"العدد 11 لا يمكن أن يكون باقي قسمة على 9"},{"quoi":"نُظهر الباقي الحقيقي","math":"<span dir=\"ltr\" class=\"expr\">11 = 9 × 1 + 2</span>"},{"quoi":"نعيد كتابة x","math":"<span dir=\"ltr\" class=\"expr\">36y + 11 = 9(4y + 1) + 2</span>"},{"quoi":"الباقي الحقيقي","math":"الباقي هو 2 لأنّ 2 < 9"},{"quoi":"الجواب","math":"خطأ"}],
