    correction: [{"quoi":"نسمّي رقم المئات","math":"نسمّي n رقم المئات، فتكون الأرقام n و <span dir=\"ltr\" class=\"expr\">n + 1</span> و <span dir=\"ltr\" class=\"expr\">n + 2</span>"},{"quoi":"شرط القسمة على 9","math":"العدد يقبل القسمة على 9 إذا كان مجموع أرقامه يقبل القسمة على 9"},{"quoi":"نحسب مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">n + (n + 1) + (n + 2) = 3n + 3</span>"},{"quoi":"نفكّك المجموع","math":"<span dir=\"ltr\" class=\"expr\">3n + 3 = 3(n + 1)</span>"},{"quoi":"المجموع ليس دائما مضاعفا لـ 9","math":"المجموع <span dir=\"ltr\" class=\"expr\">3(n + 1)</span> ليس دائما مضاعفا لـ 9: مثلا العدد 123"},{"quoi":"الجواب","math":"خطأ"}],
