    correction: [{"quoi":"نفكّك العبارة","math":"<span dir=\"ltr\" class=\"expr\">n<sup>2</sup> + n = n(n + 1)</span>"},{"quoi":"ما هو العدد الأوّلي","math":"العدد الأوّلي له قاسمان فقط: 1 و نفسه"},{"quoi":"العبارة جداء","math":"العبارة مكتوبة جداء عوامل، فهي ليست أوّلية بصفة عامّة"},{"quoi":"مثال مضادّ","math":"من أجل <span dir=\"ltr\" class=\"expr\">n = 5</span> نجد <span dir=\"ltr\" class=\"expr\">5<sup>2</sup> + 5 = 30</span>"},{"quoi":"نفكّك المثال","math":"<span dir=\"ltr\" class=\"expr\">30 = 5(5 + 1)</span>"},{"quoi":"الجواب","math":"خطأ"}],
