    correction: [{"quoi":"نبحث عن الخارج","math":"أكبر مضاعف لـ 12 لا يفوق 5152 هو <span dir=\"ltr\" class=\"expr\">12 × 429</span>"},{"quoi":"نحسب هذا المضاعف","math":"<span dir=\"ltr\" class=\"expr\">12 × 429 = 5148</span>"},{"quoi":"نحسب الباقي","math":"<span dir=\"ltr\" class=\"expr\">5152 - 5148 = 4</span>"},{"quoi":"نتحقّق من الشرط","math":"<span dir=\"ltr\" class=\"expr\">4 &lt; 12</span>"},{"quoi":"نكتب القسمة الإقليدية","math":"<span dir=\"ltr\" class=\"expr\">5152 = 12 × 429 + 4</span>"},{"quoi":"الجواب","math":"خطأ"}],
