    correction: [{"quoi":"القاعدة","math":"لا يمكن جمع قوّتين إلاّ إذا كان لهما نفس الأساس"},{"quoi":"نعيد كتابة العدد","math":"<span dir=\"ltr\" class=\"expr\">5<sup>60</sup> - 2 × 5<sup>61</sup> = 5<sup>60</sup> - 2 × 5<sup>61</sup></span>"},{"quoi":"نُخرج أصغر قوّة","math":"<span dir=\"ltr\" class=\"expr\">5<sup>60</sup> - 2 × 5<sup>61</sup> = 5<sup>60</sup>(1 - 2 × 5)</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 - 2 × 5 = -9</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">5<sup>60</sup> - 2 × 5<sup>61</sup> = -9 × 5<sup>60</sup></span>"},{"quoi":"نُظهر القاسم 15","math":"<span dir=\"ltr\" class=\"expr\">-9 × 5<sup>60</sup> = 15 × ((-3) × 5<sup>59</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">15 × (-3) × 5<sup>59</sup></span> و منه يقبل القسمة على 15"}],
