    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">125<sup>590</sup> = 5<sup>1770</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>1771</sup> + n × 5<sup>1770</sup> = 5<sup>1770</sup>(5 + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">325 = 25 × 13</span>"},{"quoi":"العامل 25 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">5<sup>1770</sup> = 5<sup>2</sup> × 5<sup>1768</sup></span>"},{"quoi":"يبقى الشرط على 13","math":"بما أنّ 13 و 5 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">5 + n</span> القسمة على 13"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">5 = 5</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 60 بحيث يقبل <span dir=\"ltr\" class=\"expr\">5 + n</span> القسمة على 13"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 8 ؛ 21 ؛ 34 ؛ 47</span>"}],
